DO $$
DECLARE
    rec record;
BEGIN
    FOR rec IN
        WITH ranked AS (
            SELECT id, email,
                   ROW_NUMBER() OVER (PARTITION BY lower(email) ORDER BY created_at, id) AS rn
            FROM users
        ),
        dups AS (
            SELECT r.id AS dup_id, k.id AS keep_id
            FROM ranked r
            JOIN ranked k ON lower(r.email) = lower(k.email) AND k.rn = 1
            WHERE r.rn > 1
        )
        SELECT dup_id, keep_id FROM dups
    LOOP
        UPDATE invoices SET billing_user_id = rec.keep_id WHERE billing_user_id = rec.dup_id;
        UPDATE orders SET user_id = rec.keep_id WHERE user_id = rec.dup_id;
        UPDATE sessions SET user_id = rec.keep_id WHERE user_id = rec.dup_id;
        UPDATE support_tickets SET user_id = rec.keep_id WHERE user_id = rec.dup_id;
        DELETE FROM users WHERE id = rec.dup_id;
    END LOOP;
END $$;

